#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    int target;
    cin >> target;

    int lo = 0, hi = n - 1, ans = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) { ans = mid; break; }
        if (a[lo] <= a[mid]) {
            // left half [lo, mid] is sorted
            if (a[lo] <= target && target < a[mid]) hi = mid - 1;
            else lo = mid + 1;
        } else {
            // right half [mid, hi] is sorted
            if (a[mid] < target && target <= a[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int m;
    cin >> m;
    vector<int> A(m);
    for (auto &x : A) cin >> x;
    int n;
    cin >> n;
    vector<int> B(n);
    for (auto &x : B) cin >> x;

    if (m > n) { swap(A, B); swap(m, n); }

    int lo = 0, hi = m, half = (m + n + 1) / 2;
    double ans = 0;
    while (lo <= hi) {
        int i = lo + (hi - lo) / 2;
        int j = half - i;
        int Aleft  = (i == 0) ? INT_MIN : A[i - 1];
        int Aright = (i == m) ? INT_MAX : A[i];
        int Bleft  = (j == 0) ? INT_MIN : B[j - 1];
        int Bright = (j == n) ? INT_MAX : B[j];

        if (Aleft <= Bright && Bleft <= Aright) {
            if ((m + n) % 2 == 0)
                ans = (max(Aleft, Bleft) + min(Aright, Bright)) / 2.0;
            else
                ans = max(Aleft, Bleft);
            break;
        } else if (Aleft > Bright) {
            hi = i - 1;
        } else {
            lo = i + 1;
        }
    }
    cout << fixed << setprecision(5) << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    long long k, n;
    cin >> k >> n;
    vector<long long> t(k);
    for (auto &x : t) cin >> x;

    long long lo = 1, hi = (long long)2e18;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        long long total = 0;
        for (auto ti : t) {
            total += mid / ti;
            if (total >= n) break;
        }
        if (total >= n) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, k;
    cin >> n >> k;
    vector<long long> a(n);
    long long lo = 0, hi = 0;
    for (auto &x : a) { cin >> x; hi += x; lo = max(lo, x); }

    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        long long parts = 1, cur = 0;
        for (auto x : a) {
            if (cur + x > mid) { parts++; cur = x; }
            else cur += x;
        }
        if (parts <= k) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    int k;
    cin >> k;

    sort(a.begin(), a.end());
    int lo = 0, hi = a[n - 1] - a[0];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long count = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            while (a[right] - a[left] > mid) left++;
            count += (right - left);
        }
        if (count >= k) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << endl;
    return 0;
}
